import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"什么是 CZero","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-czero.md","filePath":"guide/what-is-czero.md","lastUpdated":1785861127000}'),i={name:"guide/what-is-czero.md"};function d(n,e,s,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="什么是-czero" tabindex="-1">什么是 CZero <a class="header-anchor" href="#什么是-czero" aria-label="Permalink to &quot;什么是 CZero&quot;">​</a></h1><p>CZero 是一个 Android Root 清理模块，为常见的高频应用提供缓存清理，并涵盖后台压制、空文件夹清理、F2FS 垃圾回收与 fstrim。</p><p>模块本身没有常驻服务，由一个极轻量的调度进程按 <code>config.json</code> 触发所有任务，配置修改即时生效。日常操作通过原生配套应用 <strong>CZeroX</strong> 完成。</p><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>长期使用后，应用缓存与后台常驻会持续占用存储和内存，手机逐渐变卡、可用空间变少。CZero 在后台按计划自动完成清理与压制，让设备保持干净、流畅，无需手动干预。</p><h2 id="设计理念" tabindex="-1">设计理念 <a class="header-anchor" href="#设计理念" aria-label="Permalink to &quot;设计理念&quot;">​</a></h2><ul><li><strong>无常驻服务</strong> —— 不驻留任何 Java 进程，调度交给一个原生的微型进程，开销趋近于零；清理器用完即退。</li><li><strong>单一配置源</strong> —— 所有行为集中在一份 <code>config.json</code>，无中间派生文件。</li><li><strong>即时生效</strong> —— 配置变更自动热重载；配置损坏时保留上一份有效任务，绝不中断。</li><li><strong>原生前端</strong> —— 日常操作通过原生应用 CZeroX 完成，不依赖 WebUI。</li></ul><h2 id="它把东西放在哪" tabindex="-1">它把东西放在哪 <a class="header-anchor" href="#它把东西放在哪" aria-label="Permalink to &quot;它把东西放在哪&quot;">​</a></h2><p>模块自身与配置都在 <code>/data/adb/modules/CZero/</code>，其中 <code>config.json</code> 是唯一需要你关心的文件 —— 日常用 CZeroX 编辑即可。清理统计与日志也在这个目录下，卸载模块时一并清除。</p><p>清理产生的<strong>回收站</strong>不在模块目录内，而位于内置存储的 <code>Recycle</code> 文件夹，被清理的文件在此保留 7 天可恢复，详见<a href="/guide/features#回收站与恢复">功能详解 · 回收站与恢复</a>。</p><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><ul><li>Android 9+（API 28），<code>arm64-v8a</code></li><li>Root 方案：Magisk、KernelSU 或 APatch</li><li>F2FS <code>/data</code> 分区（仅 GC 功能需要，其余功能不受影响）</li></ul><p>准备好后，前往 <a href="/guide/getting-started">安装与上手</a>。</p>',13)])])}const p=a(i,[["render",d]]);export{g as __pageData,p as default};
